(4, 0, 'النواة موجبة لاحتوائها على البروتونات، وتحمل أغلب كتلة الذرة.', '["","النواة موجبة لا سالبة، وتحمل أغلب الكتلة لا نصفها.","الشحنة صحيحة، لكن النواة تحمل أغلب الكتلة لا نصفها.","النواة موجبة، والكتلة خارجها (الإلكترونات) ضئيلة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
(5, 1, 'اكتشف طومسون الإلكترون بتجارب أنبوب الأشعة المهبطية، وحسب نسبة شحنته إلى كتلته.', '["رذرفورد اكتشف النواة بتجربة صفيحة الذهب.","","أينشتاين عُرف بالنظرية النسبية وتفسير التأثير الكهروضوئي.","بويل عُرف بقانون الغازات (الضغط والحجم)."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
