(7, 0, 'العبارة الخاطئة «لا وجود للفراغ»: معظم حجم الذرة فراغ كما أثبتت تجربة رذرفورد.', '["","عبارة صحيحة من فروض دالتون.","عبارة صحيحة: الذرة أصغر جزء من العنصر يحمل خواصه.","عبارة صحيحة: لكل عنصر ذرات مميزة بعدد بروتوناتها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
