(9, 2, 'شحنة البروتون (+1) تعادل شحنة الإلكترون (−1)، فإذا تساوى عددهما كانت الشحنة الكلية صفرًا.', '["النيوترونات متعادلة فلا يؤثر عددها في الشحنة.","النيوترونات متعادلة فلا يؤثر عددها في الشحنة.","","في النواة بروتونات موجبة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
(10, 0, 'الشحنة الكلية = شحنة البروتونات (+) + شحنة الإلكترونات (−)، وعددهما متساوٍ فالمجموع صفر.', '["","مجموع شحنة الإلكترونات سالب لا صفر.","مثلا شحنة الإلكترونات سالب أيضًا لا صفر.","مجموع شحنة البروتونات موجب لا صفر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
(11, 0, 'أشعة المهبط تنحرف نحو اللوح الموجب، فهي سالبة، وهي سيل من الإلكترونات.', '["","لو كانت موجبة لانحرفت نحو اللوح السالب.","المتعادلة لا تنحرف في المجال، وأشعة المهبط تنحرف.","تنحرف في المجالين الكهربائي والمغناطيسي، فلها شحنة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
(12, 2, 'الذرة أصغر جزء من العنصر يحتفظ بخواصه.', '["الإلكترون واحد في كل العناصر، فلا يحمل خواص عنصر بعينه.","البروتون واحد في كل العناصر.","","النيوترون واحد في كل العناصر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
(13, 3, 'ارتداد قلة من الجسيمات يعني اصطدامها بجزء صغير جدًا كثيف موجب في مركز الذرة، هو النواة.', '["الذرة متعادلة، والموجب هو النواة لا الذرة كلها.","هذا ما دل عليه نفاذ معظم الجسيمات، لا ارتداد بعضها.","الإلكترونات خفيفة جدًا ولا ترد جسيم ألفا.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
(14, 3, 'المجهر الأنبوبي الماسح (STM) يمسح السطح برأس دقيق، فيُظهر صور الذرات المنفردة.', '["التلسكوب لرصد الأجرام البعيدة.","المجهر الضوئي لا يكشف أجسامًا بحجم الذرة.","المجهر الضوئي العادي لا يكفي لرؤية الذرة.",""]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
(15, 1, 'ارتداد جسيمات ألفا الموجبة يعني تنافرها مع نواة موجبة.', '["النواة السالبة كانت ستجذب جسيمات ألفا لا ترُدها.","","الجسم المتعادل لا يرد ألفا بالتنافر.","لا تنافر بلا شحنة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
(16, 0, 'هذا نموذج طومسون (نموذج كعكة الزبيب).', '["","رذرفورد جعل الشحنة الموجبة في نواة صغيرة.","مليكان قاس شحنة الإلكترون بتجربة قطرة الزيت.","كروكس طوّر أنبوب الأشعة المهبطية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb),
(17, 2, 'وصف طومسون الذرة كرة موجبة تنتشر فيها الإلكترونات.', '["بور وضع الإلكترونات في مستويات طاقة محددة.","رذرفورد جعل الموجب في نواة صغيرة.","","دالتون تصور الذرة كرة مصمتة لا تنقسم."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.084Z"}'::jsonb)
