(8, 0, 'الهيدروجين 4 والأكسجين المتبقي 2، فالناتج 2H₂O.', '["","يبقى أكسجين غير موزون.","لا يوزن الهيدروجين.","لا يوزن الهيدروجين."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:50:33.089Z"}'::jsonb),
